# Include the implementation to read private, compile-time diagnostics without
# adding public API. Feed files generated by float_coverage.py.
include brian
import std/[assertions, os, strutils]
import std/json as stdjson

when defined(brianFloatProfile):
  {.emit: "#include <valgrind/cachegrind.h>".}

proc run(path: string) =
  let texts = readFile(path).splitWhitespace()
  when defined(brianFloatStats): floatCounts = default(typeof(floatCounts))
  when defined(brianFloatVerify):
    let bitPath = path & ".bits"
    let bitLines = if fileExists(bitPath): readFile(bitPath).splitWhitespace() else: @[]
  var count = 0
  var checksum = 0'u64
  when defined(brianFloatProfile):
    {.emit: "CACHEGRIND_START_INSTRUMENTATION;".}
  for text in texts:
    let actual = fromJson(text, float64)
    when defined(brianFloatVerify):
      if bitLines.len > 0:
        var expectedBits: uint64
        doAssert parseutils.parseHex(bitLines[count], expectedBits) == 16
        doAssert cast[uint64](actual) == expectedBits, text
      var expected: float64
      doAssert parseutils.parseFloat(text, expected) == text.len, text
      doAssert cast[uint64](actual) == cast[uint64](expected), text
      doAssert cast[uint64](actual) == cast[uint64](stdjson.parseJson(text).getFloat), text
    checksum = checksum xor cast[uint64](actual)
    inc count
  when defined(brianFloatProfile):
    {.emit: "CACHEGRIND_STOP_INSTRUMENTATION;".}
  stdout.write path.extractFilename, " ", count, " ", checksum
  when defined(brianFloatStats):
    var total = 0'u64
    for kind in FloatConversion:
      stdout.write " ", $kind, "=", floatCounts[kind]
      total += floatCounts[kind]
    doAssert total == uint64(count)
  stdout.write '\n'

for path in commandLineParams(): run(path)
